func (w *writeCoalescer) writeFlusherImpl(timerC <-chan time.Time, resetTimer func()) {
	running := false

	var buffers net.Buffers
	var resultChans []chan<- writeResult
	var sizes []int64

	for {
		select {
		case req := <-w.writeCh:
			if req.data != nil {
				buffers = append(buffers, req.data)
				sizes = append(sizes, int64(len(req.data)))
			} else {
				_ = req.chain.Each(func(s wire.Span) error { buffers = append(buffers, s.Bytes()); return nil })
				sizes = append(sizes, req.chain.Len())
			}
			resultChans = append(resultChans, req.resultChan)
			if !running {
				// Start timer on first write.
				resetTimer()
				running = true
			}
		case <-w.quit:
			result := writeResult{
				n:   0,
				err: io.EOF, // TODO: better error here?
			}
			// Unblock whoever was waiting.
			for _, resultChan := range resultChans {
				// resultChan has capacity 1, so it does not block.
				resultChan <- result
			}
			return
		case <-timerC:
			running = false
			w.flushSizes(resultChans, buffers, sizes)
			buffers = nil
			resultChans = nil
			sizes = nil
			if w.testFlushedHook != nil {
				w.testFlushedHook()
			}
		}
	}
}

