func (r *InternalChainReader) Read(p []byte) (int, error) {
	if r.cursor.Remaining() == 0 {
		return 0, io.EOF
	}
	n := min(int64(len(p)), r.cursor.Remaining())
	part, err := r.cursor.Take(n)
	if err != nil {
		return 0, err
	}
	return part.CopyTo(p[:int(n)])
}

